function calculateSmartVAT({
  country,
  netAmount,
  vatCategory,
  productCategory,
  isExport,
  isB2B
}) {

// 1️⃣ Reverse Charge
  if (vatCategory === "reverse" && isB2B) {
    return buildResult(0, netAmount, "Reverse Charge");
  }

  // 2️⃣ Export
  if (isExport) {
    return buildResult(0, netAmount, "Zero Rated Export");
  }

  // 3️⃣ Exempt
  if (EXEMPT_CATEGORIES.includes(productCategory)) {
    return buildResult(0, netAmount, "Exempt");
  }

  // 4️⃣ UK Zero
  if (country === "GB" && UK_ZERO.includes(productCategory)) {
    return buildResult(0, netAmount, "Zero Rated");
  }

  // 5️⃣ UK Reduced
  if (country === "GB" && UK_REDUCED.includes(productCategory)) {
    return buildResult(config.reduced, netAmount, "Reduced VAT");
  }

  // 6️⃣ EU Reduced
  if (country !== "GB" && EU_REDUCED.includes(productCategory)) {
    return buildResult(config.reduced, netAmount, "Reduced VAT");
  }

  // 7️⃣ Fallback Standard
  return buildResult(config.standard, netAmount, "Standard VAT");
}

function buildResult(rate, netAmount, label) {

  const vatAmount = (netAmount * rate) / 100;
  const total = netAmount + vatAmount;

  return {
    rate,
    vatAmount,
    total,
    label
  };
}

